73:   private authHeaders(): HttpHeaders {
74:     const token = localStorage.getItem('access_token');
75:     return token ? new HttpHeaders({ Authorization: `Bearer ${token}` }) : new HttpHeaders();
76:   }
77: 
78:   private normalizarError(error: HttpErrorResponse, contexto: 'firmante' | 'firma' | 'ceremonia'): Error {
79:     if (error.status === 0) {
80:       return new Error('No fue posible conectar con diplomas_service. Verifique la red e intente nuevamente.');
81:     }
82:     if (contexto === 'firmante' && (error.status === 404 || error.status === 422 || error.status === 500)) {
83:       return new Error('No se encontró un firmante activo para el documento ingresado.');
84:     }
85:     if (error.status === 401 || error.status === 403) {
86:       return new Error('No tiene permisos para realizar esta acción.');
87:     }
88:     if (contexto === 'firma') {
89:       return new Error('No fue posible cargar la firma. Intente nuevamente.');
90:     }
91:     if (contexto === 'ceremonia') {
92:       return new Error('No fue posible registrar la ceremonia. Revise los datos e intente nuevamente.');
93:     }
94:     return new Error('No fue posible procesar la solicitud. Intente nuevamente.');
95:   }
96: }

