59: 
60:   /** Reapertura del consentimiento desde el aviso de la vista. Si ya se aceptó
61:    *  anteriormente se muestra el estado confirmado, no se vuelve a pedir. */
62:   consultarConsentimiento(): void {
63:     if (this.consentimientoAceptado()) {
64:       this.mostrarConsentimientoConfirmado();
65:       return;
66:     }
67:     this.mostrarConsentimientoInformado();
68:   }
69: 
70:   private mostrarConsentimientoInformado(): void {
71:     this.abrirDialogo("informado", (accion) => {
72:       if (accion === "aceptar") {
73:         this.consentimientoAceptado.set(true);
74:         this.mostrarConsentimientoConfirmado();
75:         return;
76:       }
77:       if (accion === "rechazar") {
78:         this.mostrarConsentimientoRechazado();
79:       }
80:     });
81:   }
82: 
83:   private mostrarConsentimientoConfirmado(): void {
84:     this.abrirDialogo("confirmado", () => undefined);
85:   }
86: 
87:   private mostrarConsentimientoRechazado(): void {
88:     this.abrirDialogo("rechazado", (accion) => {
89:       if (accion === "reconsentar") {
90:         this.mostrarConsentimientoInformado();
91:       }
92:     });
93:   }
94: 
95:   private abrirDialogo(
96:     vista: DatosConsentimientoDialog["vista"],
97:     alCerrar: (accion: AccionConsentimiento | undefined) => void
98:   ): void {
99:     this.dialog
100:       .open<ConsentimientoDialogComponent, DatosConsentimientoDialog, AccionConsentimiento>(
101:         ConsentimientoDialogComponent,
102:         {
103:           data: { vista },
104:           disableClose: true,
105:           autoFocus: "dialog",
106:           ariaLabel: "Consentimiento informado para el tratamiento de datos personales",
107:           width: "720px",
108:           maxWidth: "94vw",
109:         }
110:       )
111:       .afterClosed()
112:       .subscribe((accion) => {
113:         alCerrar(accion);
114:       });
115:   }
116: 
117:   regresar(): void {
118:     if (window.history.length > 1) {
119:       this.location.back();
120:       return;
121:     }
122:     this.router.navigateByUrl("/");
123:   }
124: 
125:   continuar(): void {
126:     if (this.consentimientoPendiente) {
127:       this.alertaService.showAlert(
128:         "Consentimiento requerido",
129:         "Debe aceptar el consentimiento para el tratamiento de datos personales para continuar con el diligenciamiento."
130:       );
131:       return;
132:     }
133: 
134:     if (this.formulario.invalid) {
135:       this.formulario.markAllAsTouched();
136:       this.alertaService.showAlert(
137:         "Selección requerida",
138:         "Seleccione la categoría correspondiente para continuar con el diligenciamiento."
139:       );
140:       return;
141:     }
142: 
143:     const seleccionada = this.opciones.find(
144:       (opcion) => opcion.id === this.formulario.get("modalidad")?.value
145:     );
146: 
147:     if (seleccionada) {
148:       this.modalidadSeleccionada.emit(seleccionada);
149:     }
150:   }
151: }

